module majority (
    input a, b, c,
    output out
);
    wire wire_1, wire_2, wire_3, wire_4, wire_5, wire_6, wire_7, wire_8;
    assign wire_1 = c & a;
    assign wire_2 = c & b;
    assign wire_3 = wire_1 | wire_2;
    assign wire_4 = b & a;
    assign wire_5 = wire_3 & wire_4;
    assign wire_6 = c & wire_5;
    assign wire_7 = a & wire_5;
    assign wire_8 = wire_6 | wire_7;
    assign out = wire_8;
endmodule

