{elevator_controller, elevator_controller}(
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

reg Q0, Q1;
reg [1:0] state;

always @(*) begin
    if (up_request) begin
        Q0 <= down_request;
    end
    if (reset) begin
        Q1 <= Q0;
    end
    if (clk) begin
        state = {Q1, Q0};
    end
end

assign state = { (down_request & ~Q0) | (Q1 & ~down_request), (up_request & down_request) | (Q1 & Q0) };

module circuit (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

wire [1:0] phase, inverted;
wire d, e, r, c, q;

assign inverted[0] = ~phase[0];
assign inverted[1] = ~phase[1];

assign phase[0] = clk & d;
assign phase[1] = reset & c;

assign d = inverted[0] & r | inverted[0] & d;
assign e = inverted[1] & c | inverted[1] & e;
assign r = inverted[0] & r;

assign c = r & e | r & c;

assign state[0] = inverted[1] & q | inverted[1] & c;
assign state[1] = inverted[0] & c | inverted[0] & e;

endmodule

